$status=scalar_string($_GET['status']??'');$where=$status!==''&&isset(shipment_status_labels()[$status])?' WHERE s.status=?':'';$stmt=db()->prepare('SELECT s.*,o.order_number,o.customer_name,o.phone,c.name carrier_name FROM shipments s JOIN orders o ON o.id=s.order_id LEFT JOIN shipping_carriers c ON c.id=s.carrier_id'.$where.' ORDER BY s.id DESC LIMIT 250');$stmt->execute($where?[$status]:[]);$shipments=$stmt->fetchAll();$without=db()->query("SELECT o.id,o.order_number,o.customer_name,o.order_status FROM orders o LEFT JOIN shipments s ON s.order_id=o.id WHERE s.id IS NULL AND o.payment_status IN ('paid','partially_refunded') AND o.order_status IN ('confirmed','preparing','ready_to_ship','handed_to_carrier','shipped') ORDER BY o.id DESC LIMIT 100")->fetchAll();$adminPage='shipments';$adminTitle='ارسال و رهگیری';require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>ارسال و رهگیری</h1><p class="muted">کد بارنامه، شرکت حمل و تمام رویدادهای مسیر ثبت می‌شوند.</p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/shipping.php'))?>">شرکت‌های حمل</a></div><div class="filters-admin"><a class="btn btn-secondary" href="<?=e(app_url('admin/shipments.php'))?>">همه</a><?php foreach(shipment_status_labels() as $key=>$label):?><a class="btn btn-secondary" href="<?=e(app_url('admin/shipments.php?status='.$key))?>"><?=e($label)?></a><?php endforeach?></div><?php if($without):?><div class="card"><h2>سفارش‌های آماده ساخت پرونده ارسال</h2><?php foreach($without as $order):?><a class="btn btn-secondary btn-sm" href="<?=e(app_url('admin/shipment.php?order_id='.(int)$order['id']))?>"><?=e($order['order_number'].' — '.$order['customer_name'])?></a> <?php endforeach?></div><?php endif?><div class="table-wrap"><table><thead><tr><th>پرونده</th><th>سفارش</th><th>مشتری</th><th>شرکت حمل</th><th>کد رهگیری</th><th>وضعیت</th><th>آخرین تغییر</th></tr></thead><tbody><?php foreach($shipments as $shipment):?><tr><td><a href="<?=e(app_url('admin/shipment.php?id='.(int)$shipment['id']))?>"><strong dir="ltr"><?=e($shipment['shipment_number'])?></strong></a></td><td><?=e($shipment['order_number'])?></td><td><?=e($shipment['customer_name'])?><br><small><?=e($shipment['phone'])?></small></td><td><?=e($shipment['carrier_name']?:'تعیین نشده')?></td><td dir="ltr"><?=e($shipment['tracking_code']?:'—')?></td><td><?=e(shipment_status_labels()[$shipment['status']]??$shipment['status'])?></td><td><?=e(jalali_format($shipment['updated_at']))?></td></tr><?php endforeach?><?php if(!$shipments):?><tr><td colspan="7">پرونده ارسالی ثبت نشده است.</td></tr><?php endif?></tbody></table></div>
